      'Gurke halbieren, entkernen und in Halbmonde schneiden, dann mit Joghurt, Zitronensaft und gehackter Petersilie vermengen.',
      'Die Putenfüllung mit einem Thermometer auf mindestens 74 Grad prüfen und je zwei heiße Pide mit Gurken-Joghurtsalat servieren.',
